///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        scwin.nOTICOM();
        scwin.nOTIKOSPI();
        scwin.nOTIKOSDAQ();
        MaxTab_01.setSelectedTabIndex(1);
        if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
            panel_mkt.hide();
            rdo_MKT_ID.setValue(scwin.gLdMktTp);
            $c.cm.setColumnProp(grd_Grid, "LD_MKT_TP_CD", "Show", false);
            scwin.gridInit(scwin.gLdMktTp);
        }
        scwin.init();
        scwin.headerInit();
        await scwin.setSaveHeader();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_ABBRV);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26333.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    let str = "^--선택해주세요,";
    let str2 = "";

    // str += "3333^3333,";
    str += "2222^2222,";
    for (let i = yyyy; i >= 2008; i--) {
        str += i + "^" + i + ",";
        str2 += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    str2 = str2.substring(0, str2.length - 1);
    cmb_ACNTCLS_YY.CBData = str;
};

///////// 3. 컴포넌트 이벤트 영역 /////////
