/**
 * @method
 * @name doTemplateUpload
 * @description do Template Upload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doTemplateUpload = async function() {
    let file_nm = upload_template.getValue();
    let suffix = file_nm.substring(file_nm.lastIndexOf(".") + 1);
    let wrtrptKindCd = $c.stf.getObjectText(cmb_WRTRPT_KIND_CD);
    let wrtrptKindTxt = wrtrptKindCd + '용 양식을 업로드하시겠습니까?(기존 양식은 없어짐)';
    if (!window.confirm(wrtrptKindTxt)) {
        return;
    }
    if (suffix.indexOf('xls') === -1) {
        await $c.win.alert("엑셀파일만 업로드 가능합니다.");
        return;
    }
    let chkMsg = "업로드 하시겠습니까?";
    if (window.confirm(chkMsg)) {
        scwin.gLastJob = "저장";
        const sbmOptions = {
            id : "sbm_tr_template",
            action : "/FncPrfmNewsData.do",
            ref : "dts_tmpFile",
            target : "tr_template=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

