/**
 * @method
 * @name saveAll
 * @description save All 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveAll = async function() {
    let file_nm = file.getValue();
    let suffix = file_nm.substring(file_nm.lastIndexOf(".") + 1);
    if (cmb_ACNTCLS_YY.getValue() === '') {
        await $c.win.alert("결산년도를 선택해주세요.");
        return;
    }
    if (suffix.indexOf('xls') === -1) {
        await $c.win.alert("엑셀파일만 업로드 가능합니다.");
        return;
    }
    let chkMsg = '';
    if (await scwin.checkDoubleInput() > 0) {
        chkMsg = "기존 결산자료가 등록되어있습니다.\r\n" + "삭제 후 진행해 주세요.";
        await $c.win.alert(chkMsg);
        return;
    } else {
        chkMsg = "엑셀자료를 업로드 하시겠습니까?";
    }
    if (window.confirm(chkMsg)) {
        scwin.gLastJob = "저장";
        scwin.gSDate = new Date();
        scwin.gSTimer = scwin.gSDate.getTime();
        trs_Save.Action = "/FncPrfmNewsData.do?method=registerIfrsDataAll" + "&ACNTCLS_YY=" + cmb_ACNTCLS_YY.getValue() + "&ACNTCLS_MM=" + cmb_ACNTCLS_MM.getValue() + "&WRTRPT_KIND_CD=" + cmb_WRTRPT_KIND_CD.getValue() + "&FS_WRT_METHD_CD=" + cmb_FS_WRT_METHD_CD.getValue() + "&LD_MKT_TP_CD=" + rdo_MKT_ID.getValue() + "&EMP_NO=" + js_emp_no + "&SCREN_ID=" + 'ULDSTF26333.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pFile=dts_FileList)";
        trs_Save.post();
    }
};

