/**
 * @method
 * @name dispTimer
 * @description disp Timer 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dispTimer = async function() {
    scwin.gEDate = new Date();
    scwin.gETimer = scwin.gEDate.getTime();
    const dispTimer = (scwin.gETimer - scwin.gSTimer) / 1000;
    const min = Math.round(dispTimer / 60, 2);
    const sec = Math.round(dispTimer % 60);
    await $c.win.alert("처리시간 : " + min + " 분 " + sec + "초");
};

/**
 * @method
 * @name gridInit
 * @description grid Init 처리
 * @param {String} pLdMktTp pLdMktTp
 * @returns {void}
 * @hidden N
 */
scwin.gridInit = function(pLdMktTp) {
    let isView = true;
    if (pLdMktTp === '1') {
        isView = false;
    } else if (pLdMktTp === '2') {
        isView = true;
    }
    $c.cm.setColumnProp(grd_Grid, "HDCOM_YN", "Show", !isView);
    $c.cm.setColumnProp(grd_Grid, "SECT_TP_CD", "Show", isView);
    $c.cm.setColumnProp(grd_Grid, "KOSDAQ100_YN", "Show", isView);
    $c.cm.setColumnProp(grd_Grid, "STAR30_YN", "Show", isView);
    $c.cm.setColumnProp(grd_Grid, "PREMIER_YN", "Show", isView);
    $c.cm.setColumnProp(grd_Grid, "IDX_IND_UPCLSS_CD", "Show", isView);
    $c.cm.setColumnProp(grd_Grid, "IDX_IND_MIDCLSS_CD", "Show", isView);
};

/**
 * @method
 * @name nOTICOM
 * @description n OTICOM 처리
 * @returns {void}
 * @hidden N
 */
scwin.nOTICOM = function() {
    let gMsg = "" + "1. 재무제표별로 엑셀파일을 업로드합니다.( 확장자 : xls )\n" + "    ※ (엑셀업로드시에는 엑셀이 열려있거나 문서보안이 되어있으면 업로드가 되지 않으므로\n" + "    엑셀을 닫거나  문서보안을 해제한 후에 업로드합니다.)\n" + "\n" + "2. 엑셀에 결산실적대상법인은 종목코드 6자리에 A를 붙여 입력합니다.[A+종목코드]\n" + "\n" + "3. 엑셀에 재무계정값의 수치단위는 유가 [백만원], 코스닥 [원]단위로 입력합니다.\n" + "\n" + "4. 엑셀에서 재무계정값의 추출은 엑셀헤더의 계정명과 시스템 등록된  재무계정명이 일치했을때만\n" + "    추출되므로 엑셀헤더  재무계정명은 시스템에 등록된 계정명을 입력합니다.\n" + "\n" + "5. 당기3개월, 전기3개월 계정값이 없는 경우 1분기 및 결산때에는 항목값을 '0'으로 입력합니다.\n" + "\n" + "6. 지배 순이익 계정은 연결 재무제표시에만 사용하는 계정입니다.\n" + "\n" + "7. 시스템에 등록된 이외의 계정항목(지수업종, 소속부, 프리미어지수, 스타지수)의 값은\n" + "   시스템 값을 사용합니다.";
    txa_NOTI_COM.Text = gMsg;
};

