/**
 * @method
 * @name showAlertMsg
 * @description show Alert Msg 처리
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showAlertMsg = async function(msg) {
    if (msg.indexOf('50014') !== -1) {
        await $c.win.alert('첨부하려는 파일을 열어놓은 경우, 파일 첨부가 불가능 합니다.\r\n첨부하려는 파일을 닫고 다시 진행하시기 바랍니다.');
    } else if (msg.indexOf('50073') !== -1) {
        // 연결시간 초과 메세지 이지만 어떠한 에러 없이 DB insert 잘되고, 파일 잘 만들어 져서 그냥 정상 메세지 취급
        await $c.win.alert('업로드가 완료되었습니다.');
    } else await $c.win.alert(msg);
};
